import{_ as l,c as o,o as r,a0 as t}from"./chunks/framework.DE5X-pmd.js";const u=JSON.parse('{"title":"👨‍🏫 老师使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"start/teacher.md","filePath":"start/teacher.md"}'),i={name:"start/teacher.md"};function e(n,a,s,h,d,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="👨‍🏫-老师使用指南" tabindex="-1">👨‍🏫 老师使用指南 <a class="header-anchor" href="#👨‍🏫-老师使用指南" aria-label="Permalink to &quot;👨‍🏫 老师使用指南&quot;">​</a></h1><h2 id="一、启动服务" tabindex="-1">一、启动服务 <a class="header-anchor" href="#一、启动服务" aria-label="Permalink to &quot;一、启动服务&quot;">​</a></h2><ol><li>打开 <strong>QC 启动器</strong>（桌面上的程序）</li><li>选择模式： <ul><li><strong>本地模式</strong> — 教室局域网使用（自动检测本机 IP）</li><li><strong>域名模式</strong> — 外网访问（需要配置域名）</li></ul></li><li>点击 <strong>「启动服务」</strong> 按钮</li><li>等待状态变为 🟢 绿色，弹窗会显示访问地址</li></ol><blockquote><p>提示：启动后不要关闭启动器窗口，最小化即可。</p></blockquote><hr><h2 id="二、登录后台" tabindex="-1">二、登录后台 <a class="header-anchor" href="#二、登录后台" aria-label="Permalink to &quot;二、登录后台&quot;">​</a></h2><ol><li>在浏览器中打开启动器显示的地址</li><li>点击 <strong>「登录」</strong></li><li>使用管理员或老师账号登录 <ul><li>默认管理员：<code>admin</code> / <code>111111</code></li><li>测试老师：<code>林老师(t)</code> / <code>111111</code></li></ul></li></ol><hr><h2 id="三、数据看板" tabindex="-1">三、数据看板 <a class="header-anchor" href="#三、数据看板" aria-label="Permalink to &quot;三、数据看板&quot;">​</a></h2><p>登录后默认进入数据看板，可以查看：</p><ul><li><strong>学生总数</strong> — 所有班级的学生人数</li><li><strong>班级数量</strong> — 你创建的班级数</li><li><strong>后端状态</strong> — 服务是否正常运行</li></ul><hr><h2 id="四、学生管理" tabindex="-1">四、学生管理 <a class="header-anchor" href="#四、学生管理" aria-label="Permalink to &quot;四、学生管理&quot;">​</a></h2><h3 id="查看班级和学生" tabindex="-1">查看班级和学生 <a class="header-anchor" href="#查看班级和学生" aria-label="Permalink to &quot;查看班级和学生&quot;">​</a></h3><ol><li>点击左侧导航 <strong>「学生管理」</strong></li><li>左侧显示班级列表，点击班级查看学生</li><li>点击学生 <strong>「详情」</strong> 查看该生的课堂记录</li></ol><h3 id="添加学生" tabindex="-1">添加学生 <a class="header-anchor" href="#添加学生" aria-label="Permalink to &quot;添加学生&quot;">​</a></h3><p>在班级页面点击 <strong>「添加学生」</strong>，输入学生姓名即可自动创建账号。</p><h3 id="跨班学生" tabindex="-1">跨班学生 <a class="header-anchor" href="#跨班学生" aria-label="Permalink to &quot;跨班学生&quot;">​</a></h3><p>如果一个学生被多个老师教过，查看详情时会显示<strong>全部老师的课堂记录</strong>，其他老师的记录会标注 <code>（老师名）</code>。</p><hr><h2 id="五、课堂记录" tabindex="-1">五、课堂记录 <a class="header-anchor" href="#五、课堂记录" aria-label="Permalink to &quot;五、课堂记录&quot;">​</a></h2><p>每节课后记录学生的出勤和学习情况：</p><ol><li>点击 <strong>「课堂记录」</strong></li><li>选择班级，点击 <strong>「新建记录」</strong></li><li>填写日期，逐一点击学生标注： <ul><li>✅ <strong>出勤</strong> — 正常上课</li><li>❌ <strong>缺勤</strong> — 未到（可填备注原因）</li></ul></li><li>填写本节课的<strong>学习内容</strong></li><li>点击保存</li></ol><blockquote><p>记录按月归档，可以随时查看历史记录。</p></blockquote><hr><h2 id="六、课件管理" tabindex="-1">六、课件管理 <a class="header-anchor" href="#六、课件管理" aria-label="Permalink to &quot;六、课件管理&quot;">​</a></h2><h3 id="创建课程" tabindex="-1">创建课程 <a class="header-anchor" href="#创建课程" aria-label="Permalink to &quot;创建课程&quot;">​</a></h3><ol><li>点击 <strong>「课件管理」</strong></li><li>点击 <strong>「创建课程」</strong>，输入课程名称和类型</li><li>创建后在课程下添加课件文件夹</li></ol><h3 id="上传素材" tabindex="-1">上传素材 <a class="header-anchor" href="#上传素材" aria-label="Permalink to &quot;上传素材&quot;">​</a></h3><ol><li>点击课程进入详情</li><li>点击 <strong>「上传课件」</strong></li><li>选择课件文件夹名称</li><li>上传 <code>main.sb3</code>（教师演示版）和 <code>student.sb3</code>（学生练习版）</li></ol><hr><h2 id="七、发送消息" tabindex="-1">七、发送消息 <a class="header-anchor" href="#七、发送消息" aria-label="Permalink to &quot;七、发送消息&quot;">​</a></h2><ol><li>点击 <strong>「发送消息」</strong></li><li>选择收件人（支持按班级筛选）</li><li>填写主题和内容（支持 Markdown 格式）</li><li>点击发送</li></ol><p>学生登录后在个人中心可以看到消息。</p><hr><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><p><strong>Q：学生无法访问怎么办？</strong> A：检查学生设备和老师是否在同一个网络，尝试用手机热点测试。</p><p><strong>Q：如何重置学生密码？</strong> A：联系管理员在后台重置。</p><p><strong>Q：如何添加新老师？</strong> A：使用管理员账号登录，在用户管理中添加。</p><p><strong>Q：服务启动了但浏览器打不开？</strong> A：检查防火墙是否拦截了端口（默认 80 和 8000），尝试以管理员身份运行启动器。</p>',40)])])}const b=l(i,[["render",e]]);export{u as __pageData,b as default};
